package io.rift.cronos;

import android.app.*;import android.os.*;import android.webkit.WebView;import androidx.webkit.*;
import org.json.*;import java.util.*;import java.util.concurrent.*;

/** Bounded native reads and explicitly consented local index actions. Credentials never cross this channel.
 * No arbitrary endpoint/RPC method/calldata. Fixed-gateway content references have a separate strict policy. */
public final class NativeReads implements AutoCloseable {
 private final Activity activity;private final String origin;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newSingleThreadExecutor();private final LocalWorkspace store;
 private State pending;private boolean closed;private AlertDialog consent;
 private static final class State {final String id,op,account;final JSONObject data;final JavaScriptReplyProxy reply;volatile boolean cancelled;volatile RequestControl control;Runnable timeout;JSONObject settings;
  State(String id,String op,String account,JSONObject data,JavaScriptReplyProxy reply){this.id=id;this.op=op;this.account=account;this.data=data;this.reply=reply;}}
 public NativeReads(Activity activity,String origin){this.activity=activity;this.origin=origin;store=new LocalWorkspace(activity);}
 public boolean install(WebView web){if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))return false;
  WebViewCompat.addWebMessageListener(web,"RiftRead",Collections.singleton(origin),(view,message,source,isMain,reply)->{
   if(closed||!isMain||!FilePolicy.sameOrigin(origin,source.toString()))return;String id="";
   try{JSONObject d=new JSONObject(JsonBudget.check(message.getData(),4096,4));id=WorkspacePolicy.id(d.getString("id"));if("cancel".equals(d.optString("op"))){if(pending!=null&&pending.id.equals(id))cancel("Read cancelled; no transaction was sent");return;}
    String op=ReadPolicy.operation(d.getString("op")),account="25:device";Set<String> allowed=new HashSet<>(Arrays.asList("id","op"));
    switch(op){
     case "holdings":allowed.addAll(Arrays.asList("owner","rows"));d.put("owner",ReadPolicy.address(d.getString("owner")));d.put("rows",HoldingsCheck.inputs(d.getJSONArray("rows")));account="25:"+d.getString("owner");break;
     case "balance":allowed.addAll(Arrays.asList("owner","contract"));d.put("owner",ReadPolicy.address(d.getString("owner")));String c=d.optString("contract","");if(!c.isEmpty())ReadPolicy.address(c);d.put("contract",c);account="25:"+d.getString("owner");break;
     case "artwork":case "metadata":allowed.addAll(Arrays.asList("uri","account"));account=WorkspacePolicy.account(d.getString("account"));d.put("uri",MetadataPolicy.endpoint(d.getString("uri")));break;
     case "indexStatus":case "indexStart":case "indexResume":case "indexDelete":allowed.addAll(Arrays.asList("owner","contract","standard"));d.put("owner",ReadPolicy.address(d.getString("owner")));d.put("contract",ReadPolicy.address(d.getString("contract")));d.put("standard",ReadPolicy.standard(d.getString("standard")));account="25:"+d.getString("owner");if(op.equals("indexStatus")){allowed.add("offset");DiscoveryIndex.offset(d.getString("offset"));}else{allowed.add("revision");DiscoveryIndex.revision(d.getString("revision"));if(!op.equals("indexDelete")){allowed.add("span");DiscoveryPolicy.span(d.getString("span"));}if(op.equals("indexStart")){allowed.add("fromBlock");if(!d.getString("fromBlock").equals("recent"))DiscoveryPolicy.block(d.getString("fromBlock"));}}break;
     case "discover":allowed.addAll(Arrays.asList("owner","contract","standard","fromBlock","span"));d.put("owner",ReadPolicy.address(d.getString("owner")));d.put("contract",ReadPolicy.address(d.getString("contract")));d.put("standard",ReadPolicy.standard(d.getString("standard")));if(!d.getString("fromBlock").equals("recent"))DiscoveryPolicy.block(d.getString("fromBlock"));DiscoveryPolicy.span(d.getString("span"));account="25:"+d.getString("owner");break;
     case "tokenUri":allowed.addAll(Arrays.asList("contract","tokenId","standard","account"));account=WorkspacePolicy.account(d.getString("account"));d.put("contract",ReadPolicy.address(d.getString("contract")));d.put("tokenId",ReadPolicy.token(d.getString("tokenId")));d.put("standard",ReadPolicy.standard(d.getString("standard")));break;
     case "nft":allowed.addAll(Arrays.asList("owner","contract","tokenId","standard"));d.put("owner",ReadPolicy.address(d.getString("owner")));d.put("contract",ReadPolicy.address(d.getString("contract")));d.put("tokenId",ReadPolicy.token(d.getString("tokenId")));d.put("standard",ReadPolicy.standard(d.getString("standard")));account="25:"+d.getString("owner");break;
     case "receipt":allowed.addAll(Arrays.asList("account","hash"));account=WorkspacePolicy.account(d.getString("account"));d.put("hash",ReadPolicy.hash(d.getString("hash")));break;
     case "observations":allowed.add("account");account=WorkspacePolicy.account(d.getString("account"));break;
    }
    Iterator<String> keys=d.keys();while(keys.hasNext())if(!allowed.contains(keys.next()))throw new IllegalArgumentException();
    if(pending!=null){reply(reply,id,null,"Native read is busy");return;}State s=new State(id,op,account,d,reply);pending=s;s.timeout=()->{if(pending==s)cancel("Native read timed out; no transaction was sent");};ui.postDelayed(s.timeout,120000);prepare(s);
   }catch(Exception e){reply(reply,id,null,"Read rejected: check address, token ID, hash and supported fields");}
  });return true;
 }
 private void prepare(State s){io.execute(()->{try{if(s.cancelled)return;s.settings=new SecureConnections(activity).load();String mode=s.settings.optString("mode","offline"),host=NetworkPolicy.displayHost(s.settings.optString("rpc",""));
   if(s.op.equals("status")){complete(s,new JSONObject().put("checkedAt",System.currentTimeMillis()).put("chainId",25).put("mode",mode).put("sourceHost",host).put("networkEnabled",!mode.equals("offline")).put("scope","Known assets only; no signing, arbitrary RPC, metadata hosting or full holdings discovery"),null);return;}
   if(!Arrays.asList("observations","indexStatus","indexDelete").contains(s.op)&&mode.equals("offline")){complete(s,null,"Offline mode blocks network reads. Save Direct-read or Hybrid mode in Connections & local tools.");return;}
   String gatewayHost=NetworkPolicy.displayHost(MetadataPolicy.gateway(s.settings.optString("gateway","https://ipfs.io")));String details=s.op.equals("holdings")?"Check 1–12 known NFT hints at a single hash-pinned Cronos block via saved primary RPC at "+host+".\n"+s.data.toString()+"\nSends the selected owner/contracts/token IDs to your provider. EIP-1898 canonical block-hash calls required; no latest fallback. Any provider/reorg/ABI failure rejects the whole page, not a zero balance. No automatic hint removal, save, signing, full-wallet completeness or finality assertion.":s.op.startsWith("index")?"Local discovery-index action: "+s.op+"\n"+s.data.toString()+"\nStatus/delete are local only. Start/resume send the selected public owner/contract/range to saved primary provider at "+host+" and persist a bounded native checkpoint plus up to 1000 touched-token IDs. Resume rechecks saved anchors/source revision; mismatch invalidates stored indexed hints. At most 16 scopes and 10000 accepted pages/scope. No automatic continuation, signing, current-ownership or completeness assertion. Delete removes this local scope only, not independently copied/exported browser hints or on-chain assets. In-flight local writes may commit after cancellation; reload before retrying.":s.op.equals("discover")?"Scan a bounded transfer-log page using saved primary provider at "+host+".\n"+s.data.toString()+"\nSends this public owner, contract and block range to the provider. Up to 2000 blocks, 512 log responses, 200 candidate IDs; provider may impose smaller limits. No automatic continuation. Touched-token hints include sent-away tokens and are NOT current holdings or complete wallet discovery. Page-end hash recheck is not finality. No signing, transaction or automatic candidate import.":s.op.equals("artwork")?"Fetch a bounded PNG/JPEG from saved native gateway "+gatewayHost+" and decode/re-encode a small PNG preview.\n"+s.data.getString("uri")+"\nYour IP and content path are disclosed to "+gatewayHost+". No account, credential, cookie or referrer is sent. No redirects/SVG/HTML/GIF/WebP accepted. 128 KiB input, 1 megapixel original, 256px output. Independent digest verification only for pathless CIDv1 raw sha2-256. Other paths remain unverified. This does not prove artwork ownership/authenticity.":s.op.equals("metadata")?"Fetch untrusted JSON through saved native gateway "+gatewayHost+".\n"+s.data.getString("uri")+"\nYour IP address and this content path are disclosed to "+gatewayHost+". No provider credential, wallet account, cookies, authorization or referrer are sent. No redirects, external images, HTML or SVG are fetched/rendered. 64 KiB maximum. This is NOT content-integrity verification or ownership/authenticity proof.":s.op.equals("observations")?"Read historical local observations for "+s.account+". These are NOT current ownership, order validity or proof of wallet ownership.":"Read "+s.op+" from your saved primary provider at "+host+".\n"+s.data.toString()+"\nThis sends the selected public address/hash to that provider using your saved native connection. No credential is returned to the page. It does not sign or send a transaction. No automatic backup-provider fallback.";
   ui.post(()->{if(pending!=s||s.cancelled||closed)return;consent=new AlertDialog.Builder(activity).setTitle(s.op.startsWith("index")?"Allow local discovery-index action?":"Allow this read-only check?").setMessage("Requesting page: "+origin+"\n\n"+details).setPositiveButton(s.op.startsWith("index")?"Continue once":"Read once",(d,w)->{consent=null;if(pending==s&&!s.cancelled)execute(s);}).setNegativeButton("Cancel",(d,w)->{consent=null;if(pending==s)cancel("Read cancelled");}).setOnCancelListener(d->{consent=null;if(pending==s)cancel("Read cancelled");}).show();});
  }catch(Exception e){complete(s,null,"Native connection settings unavailable; no read was sent");}});}
 private void execute(State s){io.execute(()->{try{if(s.cancelled)return;if(Arrays.asList("indexStatus","indexDelete").contains(s.op)){JSONObject current=new SecureConnections(activity).load();try(DiscoveryIndexStore index=new DiscoveryIndexStore(activity)){JSONObject value=s.op.equals("indexStatus")?DiscoveryIndex.view(index,s.data.getString("owner"),s.data.getString("contract"),s.data.getString("standard"),current.getString("_readRevision"),DiscoveryIndex.offset(s.data.getString("offset"))):DiscoveryIndex.remove(index,s.data.getString("owner"),s.data.getString("contract"),s.data.getString("standard"),current.getString("_readRevision"),DiscoveryIndex.revision(s.data.getString("revision")),()->{if(s.cancelled)throw new java.io.IOException("Cancelled");});complete(s,value,null);}return;}if(s.op.equals("observations")){JSONArray watches;ReceiptWatchStore watchStore=new ReceiptWatchStore(activity);try{watches=watchStore.list(s.account);}finally{watchStore.close();}complete(s,new JSONObject().put("cached",true).put("snapshots",bounded(store.snapshots(s.account))).put("receipts",bounded(store.receipts(s.account))).put("receiptWatches",bounded(watches)).put("warning","Historical local observations, not current ownership or finality. Each category is capped to 10 entries / 50 KiB; records may be omitted."),null);return;}
   try(RequestControl control=new RequestControl(60000)){s.control=control;if(s.cancelled)return;JSONObject current=new SecureConnections(activity).load();if(current.optString("mode","offline").equals("offline"))throw new IllegalStateException();if(!current.optString("_readRevision").equals(s.settings.optString("_readRevision"))||!current.optString("rpc").equals(s.settings.optString("rpc"))||!current.optString("key").equals(s.settings.optString("key")))throw new IllegalStateException();
    if(s.op.equals("artwork")){PinnedHttps.Result response=PinnedHttps.artwork(s.data.getString("uri"),current.optString("gateway","https://ipfs.io"),control);if(response.status!=200)throw new java.io.IOException("Image gateway unavailable");String integrity=IpfsIntegrity.check(s.data.getString("uri"),response.body);control.remaining(1000);JSONObject preview=RasterPreview.decode(response.body,response.contentType);control.remaining(1000);if(s.cancelled||!current.getString("_readRevision").equals(new SecureConnections(activity).load().getString("_readRevision")))throw new java.io.IOException("Settings changed/cancelled");complete(s,preview.put("uri",s.data.getString("uri")).put("mediaHost",NetworkPolicy.displayHost(current.optString("gateway","https://ipfs.io"))).put("checkedAt",System.currentTimeMillis()).put("cached",false).put("integrity",integrity).put("warning","Native-reencoded raster preview; not a certificate of safety, authenticity or ownership. Original content is never injected into WebView."),null);return;}
    if(s.op.equals("metadata")){PinnedHttps.Result response=PinnedHttps.metadata(s.data.getString("uri"),current.optString("gateway","https://ipfs.io"),control);if(response.status!=200)throw new java.io.IOException("Metadata gateway unavailable");String integrity=IpfsIntegrity.check(s.data.getString("uri"),response.body);String text=java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(response.body)).toString();JSONObject metadata=new JSONObject(JsonBudget.check(text,MetadataPolicy.MAX_BYTES,16));control.remaining(1000);if(s.cancelled||!current.getString("_readRevision").equals(new SecureConnections(activity).load().getString("_readRevision")))throw new java.io.IOException("Settings changed/cancelled");complete(s,new JSONObject().put("uri",s.data.getString("uri")).put("integrity",integrity).put("metadataHost",NetworkPolicy.displayHost(current.optString("gateway","https://ipfs.io"))).put("checkedAt",System.currentTimeMillis()).put("cached",false).put("metadata",metadata).put("warning","Untrusted gateway JSON. Inspect the integrity field: only pathless CIDv1 raw sha2-256 is verifiable; UnixFS/DAG paths are not. No artwork fetched or executed; no ownership/authenticity asserted."),null);return;}
    ReadOnlyRpc client=new ReadOnlyRpc(current.getString("rpc"),current.optString("key"),control);if(s.op.equals("holdings")){String source=current.getString("_readRevision");JSONObject report=HoldingsCheck.read(client,s.data.getString("owner"),s.data.getJSONArray("rows"),()->{control.remaining(1000);if(s.cancelled||!source.equals(new SecureConnections(activity).load().getString("_readRevision")))throw new java.io.IOException("Cancelled/settings changed");});complete(s,report.put("checkedAt",System.currentTimeMillis()).put("sourceHost",NetworkPolicy.displayHost(current.getString("rpc"))),null);return;}if(s.op.equals("indexStart")||s.op.equals("indexResume")){try(DiscoveryIndexStore index=new DiscoveryIndexStore(activity)){String source=current.getString("_readRevision");JSONObject value=DiscoveryIndex.advance(index,client,s.data.getString("owner"),s.data.getString("contract"),s.data.getString("standard"),source,DiscoveryIndex.revision(s.data.getString("revision")),s.op.equals("indexStart"),s.data.optString("fromBlock","recent"),s.data.getString("span"),System.currentTimeMillis(),()->{control.remaining(1000);if(s.cancelled||!source.equals(new SecureConnections(activity).load().getString("_readRevision")))throw new java.io.IOException("Cancelled/settings changed");});complete(s,value,null);}return;}JSONObject report;switch(s.op){case "discover":report=TransferDiscovery.scan(client,s.data.getString("owner"),s.data.getString("contract"),s.data.getString("standard"),s.data.getString("fromBlock"),s.data.getString("span"));break;case "tokenUri":report=client.tokenUri(s.data.getString("contract"),s.data.getString("tokenId"),s.data.getString("standard").equals("ERC-1155"));break;case "balance":report=client.balance(s.data.getString("owner"),s.data.getString("contract"));break;case "nft":report=client.nft(s.data.getString("owner"),s.data.getString("contract"),s.data.getString("tokenId"),s.data.getString("standard").equals("ERC-1155"));break;case "receipt":report=client.receipt(s.data.getString("hash"));break;default:throw new IllegalArgumentException();}
    control.remaining(1000);if(s.cancelled)return;report.put("checkedAt",System.currentTimeMillis()).put("chainId",25).put("sourceHost",NetworkPolicy.displayHost(current.getString("rpc"))).put("cached",false);
    try{if(s.op.equals("receipt"))store.receipt(s.account,s.data.getString("hash"),report);else store.snapshot(s.account,s.op+":"+s.data.optString("contract")+":"+s.data.optString("tokenId")+":"+s.data.optString("standard"),report);}catch(Exception e){report.put("cacheWarning","Read succeeded but the local observation was not saved (cache bound/storage error)");}
    complete(s,report,null);
   }
  }catch(ReadOnlyRpc.ProviderFailure e){complete(s,null,e.getMessage());}catch(Exception e){complete(s,null,"Read failed or cancelled. Check mode/provider/chain, retry later; no transaction was sent. Provider details and credentials are not exposed.");}});}
 private JSONArray bounded(JSONArray source)throws Exception{JSONArray out=new JSONArray();int bytes=0;for(int i=0;i<source.length()&&out.length()<10;i++){Object value=source.get(i);int n=value.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(bytes+n>50000)continue;out.put(value);bytes+=n;}return out;}
 private void complete(State s,Object result,String error){ui.post(()->{if(pending!=s||s.cancelled||closed)return;pending=null;ui.removeCallbacks(s.timeout);reply(s.reply,s.id,result,error);s.settings=null;});}
 private void redactProviderHost(Object value){if(value instanceof JSONObject){JSONObject object=(JSONObject)value;Iterator<String> keys=object.keys();while(keys.hasNext()){String key=keys.next();if(key.equals("sourceHost")){try{object.put(key,"Saved primary RPC (endpoint private; inspect native Connections)");}catch(JSONException ignored){}}else redactProviderHost(object.opt(key));}}else if(value instanceof JSONArray){JSONArray rows=(JSONArray)value;for(int i=0;i<rows.length();i++)redactProviderHost(rows.opt(i));}}
 private void reply(JavaScriptReplyProxy reply,String id,Object value,String error){try{redactProviderHost(value);JSONObject data=new JSONObject().put("id",id).put("ok",error==null);if(error==null)data.put("result",value==null?JSONObject.NULL:value);else data.put("error",error);String raw=data.toString();if(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>196608)raw=new JSONObject().put("id",id).put("ok",false).put("error","Read response exceeds limit").toString();if(WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER))reply.postMessage(raw);}catch(Exception ignored){}}
 private void cancel(String message){State s=pending;if(s==null)return;pending=null;s.cancelled=true;if(s.control!=null)s.control.close();s.settings=null;ui.removeCallbacks(s.timeout);if(consent!=null){consent.dismiss();consent=null;}reply(s.reply,s.id,null,message);}
 public void navigation(){cancel("Page changed; read cancelled");}
 @Override public void close(){if(closed)return;closed=true;navigation();io.execute(store::close);io.shutdown();}
}
